insert into public.tickets (id, board, number, title, type, status, urgent, deadline, location_text, places, requester, summary, submitted_by, submitted_at, meeting_ids, spans) values
  ('cb3-full-2026-09-29-G1', 'm-cb-3', 1, 'Proposal to Close Third Avenue L Stop', 'Transportation Request', 'Open', false, null, 'Third Avenue L train station', '[{"name":"3 Av (L) station, E 14 St & 3 Av","lat":40.73281,"lng":-73.98606,"source":"manual"}]'::jsonb, 'Joshua Wul', 'Public speaker asks the board to bring a proposal to the Transportation Committee and to pilot closing the Third Avenue L stop with the MTA. His simulation of 700M MTA trips claims closure saves ~1,800 hours of rider time per day. Action: route request to Transportation Committee.', 'Full Board Meeting', '2026-09-29', array['cb3-full-2026-09-29']::text[], '[{"start":1119,"end":1228,"meetingId":"cb3-full-2026-09-29"},{"start":1243,"end":2728,"meetingId":"cb3-full-2026-09-29"},{"start":2945,"end":2951,"meetingId":"cb3-full-2026-09-29"}]'::jsonb),
  ('cb3-full-2026-09-29-G2', 'm-cb-3', 2, 'East 11th Street E-Bike Obstruction Communications', 'Quality of Life Complaint', 'Open', false, null, '11th Street and First Avenue', '[{"name":"E 11 St & 1 Av","lat":40.72915,"lng":-73.98425,"source":"manual"}]'::jsonb, 'Chris Messb (public speaker); Susan (District Manager); Keith Powers; Troy (board member); Board member (unnamed)', 'Delivery-worker e-bike hub of 100+ bikes on 11th Street, with fire-hazard, closed-business and landlord complaints. 9th Precinct enforcement and bike confiscation starts Oct 7. Open actions: advance multilingual warning to workers (signs are English-only), nonprofits'' request to tag bikes for two weeks instead, finding a fenced site (Jooko) and ongoing cleaning, plus a follow-up conversation on the street''s history.', 'Full Board Meeting', '2026-09-29', array['cb3-full-2026-09-29']::text[], '[{"start":3013,"end":3079,"meetingId":"cb3-full-2026-09-29"},{"start":3151,"end":3173,"meetingId":"cb3-full-2026-09-29"},{"start":4410,"end":6250,"meetingId":"cb3-full-2026-09-29"},{"start":7183,"end":8144,"meetingId":"cb3-full-2026-09-29"},{"start":8361,"end":8371,"meetingId":"cb3-full-2026-09-29"},{"start":8549,"end":8676,"meetingId":"cb3-full-2026-09-29"},{"start":10516,"end":10522,"meetingId":"cb3-full-2026-09-29"},{"start":10625,"end":11571,"meetingId":"cb3-full-2026-09-29"},{"start":33064,"end":33315,"meetingId":"cb3-full-2026-09-29"},{"start":49056,"end":52725,"meetingId":"cb3-full-2026-09-29"},{"start":53644,"end":54411,"meetingId":"cb3-full-2026-09-29"},{"start":57661,"end":59075,"meetingId":"cb3-full-2026-09-29"},{"start":60922,"end":61132,"meetingId":"cb3-full-2026-09-29"},{"start":61328,"end":61699,"meetingId":"cb3-full-2026-09-29"},{"start":62836,"end":63567,"meetingId":"cb3-full-2026-09-29"},{"start":63591,"end":63780,"meetingId":"cb3-full-2026-09-29"},{"start":63788,"end":63929,"meetingId":"cb3-full-2026-09-29"}]'::jsonb),
  ('cb3-full-2026-09-29-G3', 'm-cb-3', 3, 'Drug Activity in Seward Park and Tompkins Square', 'Public Safety Issue', 'In Progress', false, null, 'Seward Park; Tompkins Square Park', '[{"name":"Seward Park","lat":40.71481,"lng":-73.98928,"source":"geosearch"},{"name":"Tompkins Square Park","lat":40.72645,"lng":-73.98171,"source":"geosearch"}]'::jsonb, 'Susan (District Manager); Parks Committee; Board member (unnamed)', 'Increased drug use and homelessness in Seward Park and Tompkins Square as police presence displaces activity. Open actions: fix dark spots and unlit areas in Seward Park (report outages to 311 and the office), explore mobile crisis teams instead of police, and relay complaints from Seward Park Conservancy and the LES Ecology Center to the Parks Department.', 'Full Board Meeting', '2026-09-29', array['cb3-full-2026-09-29']::text[], '[{"start":19944,"end":20073,"meetingId":"cb3-full-2026-09-29"},{"start":52726,"end":53643,"meetingId":"cb3-full-2026-09-29"},{"start":57047,"end":57399,"meetingId":"cb3-full-2026-09-29"},{"start":59437,"end":59648,"meetingId":"cb3-full-2026-09-29"},{"start":61869,"end":62794,"meetingId":"cb3-full-2026-09-29"},{"start":85723,"end":86328,"meetingId":"cb3-full-2026-09-29"}]'::jsonb),
  ('cb3-full-2026-09-29-G4', 'm-cb-3', 4, 'Allen Grill SLA Community Board Denial', 'Liquor License', 'Closed', false, null, '11 Allen Street', '[{"name":"11 Allen Street","lat":40.71493,"lng":-73.99295,"source":"geosearch"}]'::jsonb, 'Michelle (board member); Clint Smeltzer (SLA Committee); Carlin Chan (board member)', 'Board voted 20-10-9 to deny the liquor license outright (business name unclear: ''Allen Grill'' / ''Cozy Cafe''), after the committee had approved with stipulations (close 12 weekdays/2 weekends, no DJs). Open actions: add context (311 complaints, prior bar near Forsyth and Canal) to the resolution, and organize residents to attend the State Liquor Authority hearing so the denial holds. Staff will try to notify members when it is scheduled.', 'Full Board Meeting', '2026-07-28', array['cb3-full-2026-07-28', 'cb3-full-2026-09-29']::text[], '[{"start":45183,"end":47217,"meetingId":"cb3-full-2026-07-28"},{"start":47267,"end":48595,"meetingId":"cb3-full-2026-07-28"},{"start":66058,"end":67561,"meetingId":"cb3-full-2026-09-29"},{"start":67645,"end":68119,"meetingId":"cb3-full-2026-09-29"},{"start":68439,"end":71791,"meetingId":"cb3-full-2026-09-29"},{"start":72808,"end":73161,"meetingId":"cb3-full-2026-09-29"},{"start":73321,"end":74365,"meetingId":"cb3-full-2026-09-29"},{"start":74420,"end":77090,"meetingId":"cb3-full-2026-09-29"},{"start":82468,"end":82857,"meetingId":"cb3-full-2026-09-29"},{"start":83012,"end":84086,"meetingId":"cb3-full-2026-09-29"},{"start":84572,"end":85513,"meetingId":"cb3-full-2026-09-29"}]'::jsonb),
  ('cb3-full-2026-09-29-G5', 'm-cb-3', 5, 'Essex Market RFP', 'Land Use Request', 'In Progress', false, null, 'Essex Market (ground floor)', '[{"name":"Essex Market, 88 Essex Street","lat":40.71793,"lng":-73.98804,"source":"geosearch"}]'::jsonb, 'Land Use and Economic Development committees', 'EDC was unprepared to answer questions on the Essex Market RFP; board asked EDC to postpone issuing it and to confirm which resolution points are included. Action: hold follow-up meeting with EDC later this week and update the board.', 'Full Board Meeting', '2026-09-29', array['cb3-full-2026-09-29']::text[], '[{"start":77473,"end":78232,"meetingId":"cb3-full-2026-09-29"},{"start":78320,"end":78709,"meetingId":"cb3-full-2026-09-29"}]'::jsonb),
  ('cb3-full-2026-09-29-G6', 'm-cb-3', 6, 'Roller Skating Rink Proposal on East River Pier', 'Land Use Request', 'Open', false, null, 'East River pier across from Catherine Slip', '[{"name":"East River pier at Catherine Slip","lat":40.70885,"lng":-73.99435,"source":"manual"}]'::jsonb, 'Analdi Diaz (public speaker; name garbled)', 'Public speaker pitches a 300,000 sq ft, three-story roller skating rink and multi-use building on an East River pier, with $8 admission and 250-500 jobs. Action: decide whether to refer to Land Use or Economic Development committee.', 'Full Board Meeting', '2026-09-29', array['cb3-full-2026-09-29']::text[], '[{"start":11800,"end":12736,"meetingId":"cb3-full-2026-09-29"}]'::jsonb),
  ('cb3-full-2026-09-29-G7', 'm-cb-3', 7, 'Free Public Restrooms Pilot', 'Quality of Life Complaint', 'In Progress', false, null, 'Delansancy Plaza / Delansancy and Suffach (as transcribed); Cooper Square at East Sixth Street and Third Avenue', '[{"name":"Delancey St & Suffolk St","lat":40.71836,"lng":-73.98583,"source":"manual"},{"name":"Cooper Square at E 6 St & 3 Av","lat":40.72735,"lng":-73.99063,"source":"manual"}]'::jsonb, 'Mayor''s office (Obie); Transportation Committee', 'Free public restroom pilot (two in the district, installed mid-October for a year). Mayor''s office asks for nonprofit or location suggestions for tap-card access. Action: send suggestions and prepare the access-concerns resolution for next month.', 'Full Board Meeting', '2026-09-29', array['cb3-full-2026-09-29']::text[], '[{"start":31751,"end":32849,"meetingId":"cb3-full-2026-09-29"},{"start":79791,"end":81297,"meetingId":"cb3-full-2026-09-29"}]'::jsonb),
  ('cb3-full-2026-09-29-G8', 'm-cb-3', 8, 'Correct SLA Status on Soft Hours Tea House and Cozy Cafe', 'Liquor License', 'Closed', false, null, 'Softours Tea House; Cozy Cafe', '[]'::jsonb, 'Clint Smeltzer (SLA Committee)', 'Clerical errors in two August resolutions: both should recommend denial of a beer and wine license (not full on-premises) unless stipulations are agreed. Action: correct the resolutions.', 'Full Board Meeting', '2026-09-29', array['cb3-full-2026-09-29']::text[], '[{"start":64654,"end":65777,"meetingId":"cb3-full-2026-09-29"}]'::jsonb),
  ('cb3-full-2026-09-29-G9', 'm-cb-3', 9, 'Assign mentor to Leila Mahia', 'Board Administration', 'Open', false, null, 'Community Board 3 district', '[]'::jsonb, 'Board Chair (name not stated)', 'The board welcomed new member Leila Mahia and said a mentor would be assigned in the near future. Action: Assign a mentor to Leila Mahia and communicate the arrangement.', 'Full Board Meeting', '2026-09-29', array['cb3-full-2026-09-29']::text[], '[{"start":39844,"end":40047,"meetingId":"cb3-full-2026-09-29"}]'::jsonb),
  ('cb3-full-2026-09-29-G10', 'm-cb-3', 10, 'Housing Plan', 'Land Use Request', 'In Progress', false, null, 'Community Board 3 district', '[]'::jsonb, 'Board member (unnamed)', 'A board member asked whether the land-use community could provide input on the city’s housing plan on an ongoing basis, rather than only during a short comment window. The district manager said the board had already commented under a tight turnaround and emphasized the importance of committees proactively setting positions through district-needs work. Action: Identify opportunities for continued committee engagement on the housing plan and incorporate priorities, especially affordable housing, into future board positions.', 'Full Board Meeting', '2026-09-29', array['cb3-full-2026-09-29']::text[], '[{"start":56093,"end":56879,"meetingId":"cb3-full-2026-09-29"},{"start":59649,"end":60752,"meetingId":"cb3-full-2026-09-29"}]'::jsonb),
  ('cb3-full-2026-09-29-G11', 'm-cb-3', 11, 'Second Vice Chair Election', 'Board Administration', 'Closed', false, null, 'Community Board 3 district', '[]'::jsonb, 'Daniel Tano and Zachary Thomas (candidates); Board staff', 'Second vice chair election: both candidates gave two-minute speeches, ballots were handed out, collected and counted. Result: Daniel Tano 25 votes, Zachary Thomas 14 (transcript garbles the winner''s name as ''Daniel Tal''). Action: record the winner as second vice chair and update the executive committee roster.', 'Full Board Meeting', '2026-07-28', array['cb3-full-2026-07-28', 'cb3-full-2026-09-29']::text[], '[{"start":36835,"end":37585,"meetingId":"cb3-full-2026-07-28"},{"start":40163,"end":40199,"meetingId":"cb3-full-2026-09-29"},{"start":42445,"end":42500,"meetingId":"cb3-full-2026-09-29"},{"start":42831,"end":42905,"meetingId":"cb3-full-2026-09-29"},{"start":43897,"end":44062,"meetingId":"cb3-full-2026-09-29"},{"start":44813,"end":44871,"meetingId":"cb3-full-2026-09-29"},{"start":44930,"end":44973,"meetingId":"cb3-full-2026-09-29"},{"start":46975,"end":47074,"meetingId":"cb3-full-2026-09-29"},{"start":84087,"end":84348,"meetingId":"cb3-full-2026-09-29"}]'::jsonb),
  ('cb3-full-2026-09-29-G12', 'm-cb-3', 12, 'Trainings for SLA and Robert''s Rules', 'Board Administration', 'In Progress', false, null, 'Community Board 3 district', '[]'::jsonb, 'Board Chair (name not stated)', 'The board chair announced planned training on SLA matters, Robert’s Rules, and office procedures, but dates and times had not yet been set. Board members were invited to email the chair with additional training requests or questions. Action: Set and circulate dates for the announced trainings and collect any additional training topics from members.', 'Full Board Meeting', '2026-09-29', array['cb3-full-2026-09-29']::text[], '[{"start":47381,"end":48169,"meetingId":"cb3-full-2026-09-29"},{"start":48407,"end":48695,"meetingId":"cb3-full-2026-09-29"}]'::jsonb),
  ('cb3-full-2026-09-29-G13', 'm-cb-3', 13, 'FY27 Budget Priorities Vote', 'Budget Priority', 'In Progress', false, null, 'Community Board 3 district', '[]'::jsonb, 'Susan (District Manager)', 'October vote on FY27 district needs and budget priorities, ranked by agency expense and capital. Action: prepare for the vote in each committee (except SLA).', 'Full Board Meeting', '2026-07-28', array['cb3-full-2026-07-28', 'cb3-full-2026-09-29']::text[], '[{"start":41323,"end":41877,"meetingId":"cb3-full-2026-07-28"},{"start":42170,"end":42302,"meetingId":"cb3-full-2026-07-28"},{"start":49056,"end":49061,"meetingId":"cb3-full-2026-09-29"},{"start":54616,"end":55217,"meetingId":"cb3-full-2026-09-29"},{"start":55780,"end":56092,"meetingId":"cb3-full-2026-09-29"}]'::jsonb),
  ('cb3-full-2026-09-29-G14', 'm-cb-3', 14, 'Canal Street Redesign', 'Transportation Request', 'In Progress', false, null, 'Manhattan Bridge exits; Canal Street', '[{"name":"Canal St at the Manhattan Bridge","lat":40.71678,"lng":-73.99545,"source":"manual"}]'::jsonb, 'Transportation Committee', 'Letter sent to the mayor and DOT restating concerns at the foot of the Manhattan Bridge after a recent fatal crash. No Canal Street redesign update since January. Action: follow up for a response.', 'Full Board Meeting', '2026-07-28', array['cb3-full-2026-07-28', 'cb3-full-2026-09-29']::text[], '[{"start":43819,"end":44489,"meetingId":"cb3-full-2026-07-28"},{"start":81298,"end":81747,"meetingId":"cb3-full-2026-09-29"}]'::jsonb),
  ('cb3-full-2026-09-29-G15', 'm-cb-3', 15, 'Congestion Pricing Impact Update', 'Transportation Request', 'In Progress', false, null, '', '[]'::jsonb, 'Board member (unnamed)', 'Board member asks whether MTA or DOT will report back on congestion pricing, especially FDR Drive congestion after the air quality report. Action: request a report from MTA/DOT.', 'Full Board Meeting', '2026-09-29', array['cb3-full-2026-09-29']::text[], '[{"start":81986,"end":82276,"meetingId":"cb3-full-2026-09-29"}]'::jsonb),
  ('cb3-full-2026-09-29-G16', 'm-cb-3', 16, 'CEC mobile voting resolution', 'Other', 'In Progress', false, null, '', '[]'::jsonb, 'Health and Human Services Committee; Board member (unnamed)', 'Resolution urging NYC Public Schools to pilot mobile voting and expand outreach for CEC/CCEC elections (turnout around 2%). Members ask that it address equity, immigrant privacy concerns and clear ''school voting only'' language. Action: vote on resolution and add requested language.', 'Full Board Meeting', '2026-09-29', array['cb3-full-2026-09-29']::text[], '[{"start":88164,"end":90599,"meetingId":"cb3-full-2026-09-29"},{"start":90786,"end":96545,"meetingId":"cb3-full-2026-09-29"}]'::jsonb),
  ('cb3-full-2026-09-29-G17', 'm-cb-3', 17, 'Vote on Bylaws Amendments', 'Board Administration', 'In Progress', false, null, '', '[]'::jsonb, 'Bylaws Committee (Diane)', 'Proposed bylaw changes on attendance procedures, removal process and public-member conflict-of-interest rules. Action: email notice to all members at least 28 days before the October vote and clarify the double-recommendation wording.', 'Full Board Meeting', '2026-07-28', array['cb3-full-2026-07-28', 'cb3-full-2026-09-29']::text[], '[{"start":35463,"end":36632,"meetingId":"cb3-full-2026-07-28"},{"start":37631,"end":38399,"meetingId":"cb3-full-2026-07-28"},{"start":38467,"end":38927,"meetingId":"cb3-full-2026-07-28"},{"start":49262,"end":50197,"meetingId":"cb3-full-2026-07-28"},{"start":97009,"end":97253,"meetingId":"cb3-full-2026-09-29"},{"start":97334,"end":98239,"meetingId":"cb3-full-2026-09-29"},{"start":98403,"end":98864,"meetingId":"cb3-full-2026-09-29"},{"start":99212,"end":99586,"meetingId":"cb3-full-2026-09-29"},{"start":99762,"end":99984,"meetingId":"cb3-full-2026-09-29"},{"start":100142,"end":100245,"meetingId":"cb3-full-2026-09-29"}]'::jsonb),
  ('cb3-full-2026-07-28-G6', 'm-cb-3', 18, 'NYCHA Tenant Support', 'Other', 'Open', false, null, '', '[]'::jsonb, 'Unnamed resident (public speaker)', 'The Mayor''s Office of Community Engagement described door-knocking and tenant organizing in buildings with violations. A speaker asked what specific support the office will provide for NYCHA residents and families in the coming months and who its NYCHA counterpart is. Action: The office should provide specific plans for NYCHA residents and families to the board.', 'Full Board Meeting', '2026-07-28', array['cb3-full-2026-07-28']::text[], '[{"start":19577,"end":20393,"meetingId":"cb3-full-2026-07-28"},{"start":20819,"end":22688,"meetingId":"cb3-full-2026-07-28"}]'::jsonb),
  ('cb3-full-2026-07-28-G7', 'm-cb-3', 19, 'Homeless Intake Center Monitoring', 'Quality of Life Complaint', 'In Progress', false, null, 'Forest Street', '[]'::jsonb, 'District Manager (unnamed)', 'The district manager reported residents'' concerns about people gathering on Forest Street under scaffolding near the new intake center, which opens August 1. The people are not associated with the intake center or shelters and are not accepting outreach services. Action: The district manager will continue checking the block and report at the August 17 virtual community advisory board meeting for the intake center.', 'Full Board Meeting', '2026-07-28', array['cb3-full-2026-07-28']::text[], '[{"start":23874,"end":24153,"meetingId":"cb3-full-2026-07-28"},{"start":39881,"end":40938,"meetingId":"cb3-full-2026-07-28"}]'::jsonb),
  ('cb3-full-2026-07-28-G11', 'm-cb-3', 20, 'September Meeting Schedule and Location', 'Board Administration', 'Open', false, null, '', '[]'::jsonb, 'District Manager (unnamed)', 'The district manager said the meeting is held at an air-conditioned location in July because PS20 lacks air conditioning. The September full board meeting moves to the last Tuesday due to Labor Day, which pushes committee meetings back a week. Action: The district office will send the September calendar before the end of the week and confirm the return to PS20.', 'Full Board Meeting', '2026-07-28', array['cb3-full-2026-07-28']::text[], '[{"start":38928,"end":39880,"meetingId":"cb3-full-2026-07-28"}]'::jsonb),
  ('cb3-full-2026-07-28-G15', 'm-cb-3', 21, 'Clinton Street Concerns', 'Transportation Request', 'In Progress', false, null, 'Clint Street', '[]'::jsonb, 'Clint Street neighbors (public speakers); Transportation committee chair (unnamed)', 'Clinton Street neighbors presented on safety concerns on the street, and the transportation committee has long been concerned about the bike connection to the bridge at Clinton Street. The committee walked the street with DOT before a street construction project set to begin next spring. Action: The board should follow up with DOT on how the Clinton Street safety and bike connection concerns will be addressed in the spring project.', 'Full Board Meeting', '2026-07-28', array['cb3-full-2026-07-28']::text[], '[{"start":43290,"end":43818,"meetingId":"cb3-full-2026-07-28"}]'::jsonb),
  ('cb3-full-2026-07-28-G17', 'm-cb-3', 22, 'Bath House Progress', 'Other', 'Open', false, null, '', '[]'::jsonb, 'Group house task force (unnamed)', 'The group house task force report was absent, and the chair asked whether anyone had information about the bath house. No details were given in the meeting. Action: The task force should gather information about the bath house and report to the board.', 'Full Board Meeting', '2026-07-28', array['cb3-full-2026-07-28']::text[], '[{"start":53825,"end":54059,"meetingId":"cb3-full-2026-07-28"}]'::jsonb),
  ('cb3-full-2026-07-28-G19', 'm-cb-3', 23, 'Opioid treatment center closure and service relocation', 'Other', 'Open', false, null, 'Gvenir Opioid Treatment Center', '[]'::jsonb, '', 'A district manager reported that the opioid treatment center run by Mount Sinai is closing because its building was sold, and that the location of relocated services is not yet known. A community meeting on the closure is set for August 11. Action: Board to request from Mount Sinai and the relevant agencies a clear plan for where opioid treatment services will move.', 'Full Board Meeting', '2026-07-28', array['cb3-full-2026-07-28']::text[], '[{"start":40471,"end":41037,"meetingId":"cb3-full-2026-07-28"}]'::jsonb)
